    /// </description>
    /// </item>
    /// <item>
    /// <description>
    /// <c>type</c>
    /// </description>
    /// </item>
    /// </list>
    /// <para>
    /// <c>amazon_route53.resolver_query</c>
    /// </para>
    /// <list type="bullet">
    /// <item>
    /// <description>
    /// <c>transport</c>
    /// </description>
    /// </item>
    /// <item>
